5: namespace FamilyFinances.Application.Ledger.Transactions.Handlers;
6: 
7: public sealed class DeleteTransactionHandler
8: {
9:     private readonly ILedgerUnitOfWork _uow;
10:     private readonly ITransactionRepository _transactions;
11:     private readonly IFiscalYearGuard _fiscalYearGuard;
12: 
13:     public DeleteTransactionHandler(
14:         ILedgerUnitOfWork uow,
15:         ITransactionRepository transactions,
16:         IFiscalYearGuard fiscalYearGuard)
17:     {
18:         _uow = uow;
19:         _transactions = transactions;
20:         _fiscalYearGuard = fiscalYearGuard;
21:     }
22: 
23:     public async Task<bool> HandleAsync(Guid transactionId, CancellationToken ct)
24:     {
25:         var id = new TransactionId(transactionId);
26:         var tx = await _transactions.GetByIdAsync(id, ct);
27:         if (tx is null)
28:             return false;
29: 
30:         await _fiscalYearGuard.EnsureYearOpenAsync(tx.BookedOn.Year, ct);
31: 
32:         await _transactions.RemoveAsync(id, ct);
33:         await _uow.SaveChangesAsync(ct);
34:         return true;
35:     }
36: }
